namespace utilities.util;






/**
 * Some utilities for reflection using annotations
 */
public class AnnotationUtilities
{

	/**
	 * Collect from among the given class, its superclasses, and its interfaces all methods
	 * annotated with the given annotation type.
	 * 
	 * @param annotCls the annotation type
	 * @param cls the class whose methods to examine
	 * @return the set of all methods having the given annotation type
	 */
	public static Set<Method> collectAnnotatedMethods(Class<Annotation> annotCls,
			Class<object> cls) {
		Set<Method> defs = new();
		collectAnnotatedMethods(annotCls, cls, defs, new());
		return defs;
	}

	private static void collectAnnotatedMethods(Class<Annotation> annotCls, Class<object> cls,
			Set<Method> defs, Set<Class<object>> visited) {
		if (!visited.add(cls)) {
			return;
		}
		Class<object> superCls = cls.getSuperclass();
		if (superCls != null) {
			collectAnnotatedMethods(annotCls, superCls, defs, visited);
		}
		foreach (Class<object> superIf in cls.getInterfaces()) {
			collectAnnotatedMethods(annotCls, superIf, defs, visited);
		}
		collectAnnotatedMethodsForClass(annotCls, cls, defs);
	}

	private static void collectAnnotatedMethodsForClass(Class<Annotation> annotCls,
			Class<object> cls, Set<Method> defs) {
		foreach (Method method in cls.getDeclaredMethods()) {
			Annotation annot = method.getAnnotation(annotCls);
			if (annot == null) {
				continue;
			}
			defs.add(method);
		}
	}
}
